// The exact request for one saved article (built from storage), and the delivery's starting state.
const crypto = require('crypto');
const input = $('Delivery request').first().json;
const row = $('Build request').first().json;
const fail = (status, reason) => [{ json: { action: 'finish', stopped: { status, reason }, articleId: input.articleId } }];
if (!row.request) return fail('not-found', 'article-not-found');
const target = input.target === 'fake' ? 'fake' : 'service';
let baseUrl;
if (target === 'fake') baseUrl = 'http://127.0.0.1:5678/webhook/steele-exp/fake-draft';
else {
  if (row.enabled !== '1') return fail('disabled', 'delivery-disabled');
  if (!/^https?:\/\/[^\s/?#]+$/.test(String(row.url ?? ''))) return fail('disabled', 'draft-service-url-not-configured');
  baseUrl = row.url;
}
const request = { ...row.request };
// Test-only: a changed payload under the same request ID, to prove the service refuses it (fake target only).
if (target === 'fake' && input.mutate === 'title') request.title = `${request.title} (changed)`;
const payloadSha256 = crypto.createHash('sha256').update(JSON.stringify(request), 'utf8').digest('hex');
// The real service's routes; the test double serves the same operations on fixed n8n webhook paths
// (n8n path parameters need a webhook-ID prefix), taking the request ID as a query parameter.
const id = encodeURIComponent(request.requestId);
const urls = target === 'fake'
  ? { deliver: `${baseUrl}/v1/drafts`, reconcile: `${baseUrl}/v1/reconcile?id=${id}`, status: `${baseUrl}/v1/status?id=${id}` }
  : { deliver: `${baseUrl}/v1/drafts`, reconcile: `${baseUrl}/v1/deliveries/${id}/reconcile`, status: `${baseUrl}/v1/deliveries/${id}?refresh=1` };
return [{ json: { action: null, articleId: input.articleId, target, urls, request, requestId: request.requestId, payloadSha256,
  tries: 0, mustReconcile: false, maybeCreated: false, readbackTried: false, last: null, history: [] } }];

const MAX_TRIES = 3;
const s = $json;
if (s.action === 'finish' && s.stopped) return [{ json: s }];
const SETTLED_OK = ['created', 'existing'];
const NEVER_RETRY = ['conflict', 'invalid', 'forbidden', 'not-found', 'unauthorised'];
const verified = (r) => r?.readback?.titleMatches === true && r.readback.published === false && r.readback.emailSent === false;
const last = s.last;
const settled = last && (SETTLED_OK.includes(last.status) || NEVER_RETRY.includes(last.status));
let action;
if (settled || s.tries >= MAX_TRIES) {
  // A settled success without strict readback evidence gets one fresh readback through the service.
  action = last && SETTLED_OK.includes(last.status) && !verified(last) && !s.readbackTried ? 'status' : 'finish';
} else action = s.mustReconcile ? 'reconcile' : 'deliver';
return [{ json: { ...s, action } }];

// Reads one answer from the draft service. No usable answer means the request may have been acted on.
const s = $('Next step').last().json;
const r = $json;
let body = null;
if (!r.error && typeof r.data === 'string') { try { body = JSON.parse(r.data); } catch { body = null; } }
const answered = body && typeof body === 'object' && typeof body.status === 'string';
const httpStatus = r.statusCode ?? null;
const next = { ...s, history: [...s.history] };
const sleep = (ms) => new Promise((res) => setTimeout(res, ms));
if (s.action === 'status') {
  next.readbackTried = true;
  next.history.push({ try: s.history.length + 1, action: 'readback', status: answered ? body.status : 'unreachable', httpStatus });
  if (answered && body.readback) next.last = { ...s.last, readback: body.readback, draftId: body.draftId ?? s.last.draftId, receiptId: body.receiptId ?? s.last.receiptId };
  return [{ json: next }];
}
next.tries = s.tries + 1;
if (!answered) {
  next.history.push({ try: next.tries, action: s.action, status: 'unreachable', httpStatus });
  next.last = null; next.maybeCreated = true; next.mustReconcile = true;
  await sleep(500 * next.tries);
  return [{ json: next }];
}
const resp = { status: body.status, httpStatus, draftId: body.draftId ?? null, receiptId: body.receiptId ?? null,
  editorUrl: body.editorUrl ?? null, readback: body.readback ?? null, error: body.error ?? null };
next.history.push({ try: next.tries, action: s.action, status: resp.status, httpStatus });
next.last = resp;
// The service never recorded the request, so a create is safe.
if (s.action === 'reconcile' && resp.status === 'not-found') { next.mustReconcile = false; next.maybeCreated = false; next.last = null; return [{ json: next }]; }
if (resp.status === 'uncertain') next.maybeCreated = true;
if (resp.status === 'failed') next.maybeCreated = false;
next.mustReconcile = resp.status === 'uncertain';
if (!['created', 'existing', 'conflict', 'invalid', 'forbidden', 'not-found', 'unauthorised'].includes(resp.status)) await sleep(500 * next.tries);
return [{ json: next }];

// The delivery's outcome. created/existing count only with strict readback evidence; an unanswered
// create stays 'uncertain' (reconcile later, never re-create blindly).
const s = $json;
if (s.stopped) return [{ json: { record: false, articleId: s.articleId, status: s.stopped.status, error: s.stopped.reason } }];
const SETTLED_OK = ['created', 'existing'];
const verified = (r) => r?.readback?.titleMatches === true && r.readback.published === false && r.readback.emailSent === false;
const last = s.last;
const status = last && SETTLED_OK.includes(last.status) ? (verified(last) ? last.status : 'unverified')
  : s.maybeCreated ? 'uncertain' : (last?.status ?? 'unreachable');
return [{ json: { record: true, requestId: s.requestId, articleId: s.articleId, target: s.target, payloadSha256: s.payloadSha256, status,
  draftId: last?.draftId ?? null, receiptId: last?.receiptId ?? null, readback: last?.readback ?? null,
  history: s.history, error: last?.error ?? null, source: s.request.source, article: s.request.article } }];

// The run's visible result. The private editor link is not returned here; it stays with the service.
const o = $('Outcome').first().json;
const ok = ['created', 'existing'].includes(o.status);
return [{ json: { httpStatus: ok ? 200 : o.status === 'not-found' ? 404 : o.status === 'disabled' ? 409 : 502, ...o, record: undefined,
  recorded: $json.result ?? null } }];
